     *
     */
    interface iAuthenticate extends \Luracast\Restler\iFilter
    {
        /**
         * @return string string to be used with WWW-Authenticate header
         * @example Basic
         * @example Digest
         * @example OAuth
         */
        public function __getWWWAuthenticateString();
    }
