        public static $form;
        /**
         * @var Validate|null 	Validate handler.
         */
        public static $validator;
        /**
         * @var array<int,mixed> 	List of value deemed as empty (null always deemed as empty)
         */
        public $emptyValues = array('', 0, array());
        /**
         * Constructor
