        const NUM_EXTENSION_BLOCK_POS = 0x48;
        const BIG_BLOCK_DEPOT_BLOCKS_POS = 0x4c;
        // property storage offsets (directory offsets)
        const SIZE_OF_NAME_POS = 0x40;
        const TYPE_POS = 0x42;
        const START_BLOCK_POS = 0x74;
        const SIZE_POS = 0x78;
