     */
    interface SharingSupport extends \Sabre\CalDAV\Backend\BackendInterface
    {
        /**
         * Updates the list of shares.
         *
         * @param mixed                           $calendarId
         * @param \Sabre\DAV\Xml\Element\Sharee[] $sharees
         */
