        const SO_NOSERVER = 16;
        const SA_MESSAGES = 1;
        const SA_RECENT = 2;
        const SA_UNSEEN = 4;
        const SA_UIDNEXT = 8;
        const SA_UIDVALIDITY = 16;
        const SA_ALL = 31;
