        const SORTSIZE = 6;
        const TYPETEXT = 0;
        const TYPEMULTIPART = 1;
        const TYPEMESSAGE = 2;
        const TYPEAPPLICATION = 3;
        const TYPEAUDIO = 4;
        const TYPEIMAGE = 5;
        const TYPEVIDEO = 6;
        const TYPEMODEL = 7;
        const TYPEOTHER = 8;
        const ENC7BIT = 0;
        const ENC8BIT = 1;
        const ENCBINARY = 2;
        const ENCBASE64 = 3;
        const ENCQUOTEDPRINTABLE = 4;
        const ENCOTHER = 5;
        /**
